// Expo config plugin for the guest runtime (src/apps/guest). android/ is generated by prebuild and not committed, so
// what the guest needs in it is written here, once, however often prebuild runs:
// - MainApplication hands the app's autolinked packages (but Expo's) to the sandbox, so the kit's native modules and views can exist
//   inside a guest (which ones a guest may use is the host's allow list, src/apps/guest/modules.ts);
// - the gradle build runs guest/build-base.sh and puts its output (the base bundle, and the lab fixtures in a lab
//   build) into the APK assets.
// The R8 keep rule for the sandbox is in app.json (expo-build-properties extraProguardRules).
const { withAppBuildGradle, withMainApplication } = require("expo/config-plugins");

// Not Expo's package: asked for modules or views it starts an Expo app context for the guest that is never torn down
// (two threads and about 5 MB left per mount), and a guest has no Expo module anyway.
const REGISTER =
  "io.callstack.rnsandbox.SandboxReactNativeDelegate.registerHostPackages(PackageList(this).packages.filterNot { it is expo.modules.ExpoModulesPackage })";
const AFTER = "loadReactNative(this)";
const MARK = "// lophn guest runtime assets";

const GRADLE = `
${MARK}
def lophnGuestOut = new File(buildDir, "generated/lophn-guest")
def lophnMobile = new File(projectDir, "../..").canonicalFile
def lophnPackages = new File(lophnMobile, "..").canonicalFile
tasks.register("lophnGuestAssets", Exec) {
    workingDir lophnMobile
    commandLine "sh", "guest/build-base.sh", lophnGuestOut.absolutePath
    inputs.property("lab", System.getenv("EXPO_PUBLIC_LOPHN_GUEST_LAB") ?: "")
    inputs.files(
        fileTree(new File(lophnMobile, "guest")),
        fileTree(new File(lophnPackages, "design/native")),
        fileTree(new File(lophnPackages, "design/i18n")),
        fileTree(new File(lophnPackages, "sdk/app-ui-native")),
        fileTree(new File(lophnPackages, "sdk/app-ui")),
        new File(lophnPackages, "protocol/apps/phone-screen.ts"),
        new File(lophnMobile, "package-lock.json"),
        new File(lophnMobile, "metro.config.js"),
    )
    outputs.dir(new File(lophnGuestOut, "guest"))
}
android.sourceSets.main.assets.srcDirs += [lophnGuestOut.absolutePath]
preBuild.dependsOn("lophnGuestAssets")
`;

module.exports = function withGuestRuntime(config) {
  config = withMainApplication(config, (mod) => {
    if (!mod.modResults.contents.includes(REGISTER)) {
      if (!mod.modResults.contents.includes(AFTER)) {
        throw new Error(`with-guest-runtime: MainApplication has no ${AFTER}`);
      }
      mod.modResults.contents = mod.modResults.contents.replace(
        AFTER,
        `${AFTER}\n    ${REGISTER}`,
      );
    }
    return mod;
  });
  return withAppBuildGradle(config, (mod) => {
    if (!mod.modResults.contents.includes(MARK)) {
      mod.modResults.contents += GRADLE;
    }
    return mod;
  });
};
